changeSet.sql:
ALTER TABLE zc_enrolment
  ADD CONSTRAINT fk_zc_enrolment_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_enrolment
  ADD CONSTRAINT fk_zc_enrolment_member FOREIGN KEY (tenant_id, member_id)
    REFERENCES zc_member_reference (tenant_id, id);
ALTER TABLE zc_enrolment
  ADD CONSTRAINT fk_zc_enrolment_programme FOREIGN KEY (tenant_id, programme_id)
    REFERENCES zc_programme (tenant_id, id);
-- Version must belong to the enrolled programme.
ALTER TABLE zc_enrolment
  ADD CONSTRAINT fk_zc_enrolment_programme_version FOREIGN KEY (tenant_id, programme_version_id, programme_id)
    REFERENCES zc_programme_version (tenant_id, id, programme_id);
ALTER TABLE zc_enrolment
  ADD CONSTRAINT fk_zc_enrolment_cohort_membership FOREIGN KEY (tenant_id, cohort_membership_id, member_id)
    REFERENCES zc_cohort_membership (tenant_id, id, member_id);
ALTER TABLE zc_enrolment
  ADD CONSTRAINT fk_zc_enrolment_supersedes FOREIGN KEY (tenant_id, supersedes_enrolment_id, member_id)
    REFERENCES zc_enrolment (tenant_id, id, member_id);

ALTER TABLE zc_consent_record
  ADD CONSTRAINT fk_zc_consent_record_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
-- Consent member must match the enrolment member.
ALTER TABLE zc_consent_record
  ADD CONSTRAINT fk_zc_consent_record_enrolment FOREIGN KEY (tenant_id, enrolment_id, member_id)
    REFERENCES zc_enrolment (tenant_id, id, member_id);
ALTER TABLE zc_consent_record
  ADD CONSTRAINT fk_zc_consent_record_member FOREIGN KEY (tenant_id, member_id)
    REFERENCES zc_member_reference (tenant_id, id);

ALTER TABLE zc_member_preference
  ADD CONSTRAINT fk_zc_member_preference_tenant FOREIGN KEY (tenant_id) REFERENCES zc_tenant (id);
ALTER TABLE zc_member_preference
  ADD CONSTRAINT fk_zc_member_preference_member FOREIGN KEY (tenant_id, member_id)
    REFERENCES zc_member_reference (tenant_id, id);

CREATE TRIGGER trg_zc_enrolment_pins
  BEFORE UPDATE ON zc_enrolment
  FOR EACH ROW EXECUTE FUNCTION zc_forbid_pinned_change(
    'trg_zc_enrolment_pins', 'member_id', 'programme_id', 'programme_version_id');
CREATE TRIGGER trg_zc_enrolment_touch BEFORE UPDATE ON zc_enrolment FOR EACH ROW EXECUTE FUNCTION zc_touch_row();

-- Tenant isolation. The app must connect as zc_app: superusers bypass RLS.
ALTER TABLE zc_enrolment ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_enrolment FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_enrolment_tenant ON zc_enrolment
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_consent_record ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_consent_record FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_consent_record_tenant ON zc_consent_record
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());
ALTER TABLE zc_member_preference ENABLE ROW LEVEL SECURITY;
ALTER TABLE zc_member_preference FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_zc_member_preference_tenant ON zc_member_preference
  USING (tenant_id = zc_current_tenant())
  WITH CHECK (tenant_id = zc_current_tenant());

rollback.sql:
DROP POLICY rls_zc_enrolment_tenant ON zc_enrolment;
ALTER TABLE zc_enrolment NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_enrolment DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_consent_record_tenant ON zc_consent_record;
ALTER TABLE zc_consent_record NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_consent_record DISABLE ROW LEVEL SECURITY;
DROP POLICY rls_zc_member_preference_tenant ON zc_member_preference;
ALTER TABLE zc_member_preference NO FORCE ROW LEVEL SECURITY;
ALTER TABLE zc_member_preference DISABLE ROW LEVEL SECURITY;

changeSet.sql:
GRANT SELECT, INSERT, UPDATE ON zc_enrolment TO zc_app;
GRANT USAGE ON SEQUENCE zc_enrolment_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_consent_record TO zc_app;
GRANT USAGE ON SEQUENCE zc_consent_record_id_seq TO zc_app;
GRANT SELECT, INSERT, UPDATE ON zc_member_preference TO zc_app;
GRANT USAGE ON SEQUENCE zc_member_preference_id_seq TO zc_app;

rollback.sql:
REVOKE ALL ON zc_enrolment FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_enrolment_id_seq FROM zc_app;
REVOKE ALL ON zc_consent_record FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_consent_record_id_seq FROM zc_app;
REVOKE ALL ON zc_member_preference FROM zc_app;
REVOKE USAGE ON SEQUENCE zc_member_preference_id_seq FROM zc_app;
